mkdir -p /tmp/chipzstress && cd /tmp/chipzstress && cat > gen.py <<'EOF'
import zlib, random, subprocess, os
random.seed(7)
d = "/tmp/chipzstress/data"
os.makedirs(d, exist_ok=True)
def mixed(n_segments):
    out = bytearray()
    for _ in range(n_segments):
        if random.random() < 0.5:
            out += bytes(random.getrandbits(8) for _ in range(random.randint(1, 70000)))
        else:
            out += (b"line %d of some sensor text\n" % random.randint(0, 999)) * random.randint(1, 3000)
    return bytes(out)
inputs = {"rec": open("/tmp/chipzrepro/recording.bin","rb").read(),
          "mix1": mixed(6), "mix2": mixed(10), "small": b"line 0\nline 1\n" + os.urandom(70000),
          "tiny": b"hello", "empty": b""}
for name, data in inputs.items():
    open(f"{d}/{name}.raw","wb").write(data)
    for lvl in (1, 6, 9):
        open(f"{d}/{name}-{lvl}.gzip","wb").write(subprocess.run(["gzip", f"-{lvl}", "-n", "-c"], input=data, capture_output=True).stdout)
    for lvl in (0, 1, 9):
        open(f"{d}/{name}-{lvl}.zlib","wb").write(zlib.compress(data, lvl))
        c = zlib.compressobj(lvl, zlib.DEFLATED, -15); open(f"{d}/{name}-{lvl}.deflate","wb").write(c.compress(data)+c.flush())
EOF
